insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://static.wixstatic.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);

insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Barrell Gold Label Dovetail","rar":"unicorn","f":"Barrell","x":"Gold Label Dovetail","p":140.18,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"blend","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://static.wixstatic.com/media/12d4f8_1ccd383188f848558a7f4ee23973de17~mv2.png","u":"https://www.barrellbourbon.com/golddovetail","pr":"Barrell","mk":"bda3518f-508d-4d9c-b3b8-9dea704ee024"},{"n":"Barrell Infinite Barrel Project","rar":"allocated","f":"Barrell","x":"Infinite Barrel Project","p":123.44,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":["Barrell Whiskey: Infinite Barrel Project"],"img":null,"u":"https://www.barrellbourbon.com/infinite","pr":"Barrell","mk":"bda3518f-508d-4d9c-b3b8-9dea704ee024"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');

